CREATE TABLE IF NOT EXISTS "private"."messages"(id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY, public_chat_id bigint NULL REFERENCES "public"."chats"(id), private_chat_id bigint NULL REFERENCES "private"."chats"(id),"author_id" varchar(36) NOT NULL REFERENCES "keycloak".user_entity(id), "receiver_id" varchar(36) NOT NULL REFERENCES "keycloak".user_entity(id), encrypted_message varchar(500) NOT NULL, created_at timestamp NOT NULL DEFAULT now(), modified_at timestamp NULL, deleted_for_all bool default false, deleted_for_author_only bool default false);
